package com.match.transfer;import com.baomidou.mybatisplus.core.mapper.BaseMapper;import org.apache.ibatis.annotations.*;import java.time.LocalDateTime;import java.util.List;
public interface TemporaryTransferMapper extends BaseMapper<TemporaryTransferRecord>{@Select("SELECT * FROM temporary_training_transfer WHERE command_id=#{id} LIMIT 1")TemporaryTransferRecord selectByCommand(@Param("id")String id);@Select("SELECT * FROM temporary_training_transfer WHERE user_id=#{id} ORDER BY created_at DESC LIMIT 100")List<TemporaryTransferRecord> selectByUser(@Param("id")int id);@Select("SELECT * FROM temporary_training_transfer WHERE expires_at<#{now} AND state<>'SUCCEEDED'")List<TemporaryTransferRecord> selectExpired(@Param("now")LocalDateTime now);}
